package com.autoops.infrastructure.remote;import com.jcraft.jsch.*;import org.springframework.stereotype.Component;import java.io.*;import java.nio.charset.StandardCharsets;@Component public class SshRemoteClient implements RemoteClient{private Session session(String h,int p,String u,String pw)throws Exception{JSch j=new JSch();Session s=j.getSession(u,h,p);s.setPassword(pw);s.setConfig("StrictHostKeyChecking","yes");s.connect(10000);return s;}public Result test(String h,int p,String u,String pw){try{Session s=session(h,p,u,pw);s.disconnect();return new Result(true,0,"connected","");}catch(Exception e){return new Result(false,-1,"",e.getMessage());}}public Result execute(String h,int p,String u,String pw,String cmd,int timeout){Session s=null;try{s=session(h,p,u,pw);ChannelExec c=(ChannelExec)s.openChannel("exec");c.setCommand(cmd);ByteArrayOutputStream err=new ByteArrayOutputStream();c.setErrStream(err);InputStream in=c.getInputStream();c.connect(timeout*1000);String out=new String(in.readAllBytes(),StandardCharsets.UTF_8);while(!c.isClosed())Thread.sleep(50);int code=c.getExitStatus();c.disconnect();return new Result(code==0,code,out,err.toString(StandardCharsets.UTF_8));}catch(Exception e){return new Result(false,-1,"",e.getMessage());}finally{if(s!=null)s.disconnect();}}public Result upload(String h,int p,String u,String pw,InputStream data,String destination,long size){Session s=null;try{s=session(h,p,u,pw);ChannelSftp c=(ChannelSftp)s.openChannel("sftp");c.connect(10000);c.put(data,destination);c.disconnect();return new Result(true,0,destination,"");}catch(Exception e){return new Result(false,-1,"",e.getMessage());}finally{if(s!=null)s.disconnect();}}}
